export class StaleSessionError extends Error {
    constructor(){
        super("session changed during replay");
        this.name = "StaleSessionError";
    }
}
export function sessionScoped(generation, currentGeneration, action) {
    return (...args)=>{
        if (currentGeneration() !== generation) throw new StaleSessionError();
        return action(...args);
    };
}
export async function sessionScopedResult(generation, currentGeneration, action) {
    if (currentGeneration() !== generation) throw new StaleSessionError();
    const result = await action();
    if (currentGeneration() !== generation) throw new StaleSessionError();
    return result;
}
export async function sessionScopedCommit(generation, currentGeneration, action, commit) {
    if (currentGeneration() !== generation) throw new StaleSessionError();
    const result = await action();
    if (currentGeneration() !== generation) throw new StaleSessionError();
    // The commit is deliberately synchronous with the post-await generation
    // check, leaving no microtask gap in which a device switch can intervene.
    return commit(result);
}
